let lg=0;const $=s=>document.querySelector(s);
const st={hs:null,step:null,myth:new Set(),chk:new Set([0,1,2,3,4,5,6])};
const U={
sub:['الليمفوما أقرب مما تتصوّر: رحلة هادئة داخل الجهاز الليمفاوي لفهم الأعراض والتشخيص والعلاج.','A calm journey through the lymphatic system to understand lymphoma: symptoms, diagnosis and treatment.'],
cta1:['استكشف الجهاز الليمفاوي','Explore the Lymphatic System'],cta2:['تعرّف على الليمفوما','Understand Lymphoma'],
introH:['لماذا نفهم الجهاز الليمفاوي؟','Why understand the lymphatic system?'],
introP:['الجهاز الليمفاوي شبكة من العقد والأوعية والأعضاء تساعد الجسم على مقاومة العدوى وتصريف السوائل. الليمفوما سرطان يبدأ في الخلايا الليمفاوية، وفهمك للأساسيات يساعدك على طرح الأسئلة الصحيحة.','The lymphatic system is a network of nodes, vessels and organs that helps the body fight infection and drain fluid. Lymphoma is a cancer that starts in lymphocytes, and knowing the basics helps you ask the right questions.'],
disc:['يقدّم هذا الموقع معلومات توعوية عامة عن الليمفوما والجهاز الليمفاوي، ولا يُعد بديلًا عن التشخيص أو المشورة الطبية المتخصصة. إذا كانت لديك أعراض مستمرة أو مقلقة، فاستشر مختصًا بالرعاية الصحية.','This website provides general educational information about lymphoma and the lymphatic system. It is not a substitute for professional medical advice or diagnosis. If you have persistent or concerning symptoms, consult a qualified healthcare professional.'],
exploreH:['استكشف الجهاز الليمفاوي','Explore the Lymphatic System'],
exploreP:['اختر أي نقطة مضيئة بالفأرة أو اللمس أو لوحة المفاتيح (Tab ثم Enter) لقراءة تفاصيلها. النقاط الملوّنة بالمرجاني هي المختارة حاليًا.','Select any glowing point with mouse, touch or keyboard (Tab then Enter) to read about it. The coral point is the one currently selected.'],
schem:['الرسم تخطيطي مبسّط لأغراض التعليم وليس دقيقًا تشريحيًا، وتضخّم أي عقدة لا يعني بالضرورة السرطان، وقد تظهر الليمفوما في مواضع مختلفة.','This is a simplified schematic for education, not anatomically precise. An enlarged node does not necessarily mean cancer, and lymphoma can appear in different places.'],
pick:['اختر نقطة من الرسم.','Select a point on the illustration.'],lblName:['الاسم','Name'],lblLoc:['الموقع','Location'],lblRole:['الدور','Role'],lblLym:['الصلة بالليمفوما','Relevance to lymphoma'],
lymH:['ما هي الليمفوما؟','What is lymphoma?'],
lymP:['الليمفوما سرطان يبدأ في الخلايا الليمفاوية، وهي خلايا مناعية تنتقل عبر الجهاز الليمفاوي والدم. عندما تنمو هذه الخلايا بصورة غير طبيعية قد تتجمع في العقد أو الأعضاء الليمفاوية أو مواضع أخرى. تتنوع الأنواع في سلوكها وعلاجها، لذلك يعتمد التشخيص والخطة العلاجية على النوع المحدد وعلى ظروف كل شخص.','Lymphoma is a cancer that starts in lymphocytes, immune cells that travel through the lymphatic system and blood. When these cells grow abnormally they can collect in nodes, lymphatic organs or other sites. Types differ in how they behave and are treated, so diagnosis and treatment depend on the specific type and each person’s circumstances.'],
cmp:[['الخاصية','Feature'],['ليمفوما هودجكين','Hodgkin lymphoma'],['ليمفوما لاهودجكين','Non-Hodgkin lymphoma']],
cmpRows:[['تحت المجهر','Under the microscope','تتميّز بوجود خلايا ريد-ستيرنبرغ.','Characterised by Reed–Sternberg cells.','لا تتميّز بهذه الخلايا.','Does not have this defining feature.'],
['التنوع','Variety','تضم عدة أنواع فرعية معروفة.','Includes several recognised subtypes.','ليست مرضًا واحدًا بل مجموعة واسعة من الأمراض المختلفة، منها ما ينشأ من الخلايا البائية أو التائية.','Not one disease but a broad group of different diseases, arising from B cells or T cells.'],
['العلاج','Treatment','يعتمد على النوع الفرعي ومدى الانتشار والحالة الصحية.','Depends on subtype, extent and general health.','يختلف كثيرًا بين نوع وآخر؛ وقد تُناسب بعض الحالات المراقبة النشطة.','Varies widely between types; some cases suit active surveillance.']],
symH:['الأعراض والعلامات','Symptoms and warning signs'],
symP:['هذه الأعراض شائعة ولها أسباب كثيرة أغلبها غير خطير، ولا تُثبت وحدها تشخيص الليمفوما. لا يقدّم الموقع أداة لتقدير احتمال الإصابة.','These symptoms are common and have many causes, most not serious, and do not on their own establish a lymphoma diagnosis. This site offers no tool to estimate your chance of having it.'],
symWhen:['متى تراجع الطبيب؟','When to seek assessment'],
urgent:['صعوبة التنفس أو أي أعراض شديدة تتفاقم بسرعة تستدعي رعاية طبية عاجلة. اطلب المساعدة الطارئة فورًا.','Difficulty breathing or any severe, rapidly worsening symptom needs urgent medical attention. Seek emergency help right away.'],
diagH:['رحلة التشخيص','The diagnostic journey'],
diagP:['اختر مرحلة لقراءة شرحها. لا يخضع كل شخص للفحوص نفسها أو بالتسلسل نفسه؛ فالمسار يتحدد بحالتك. الفحوص الدموية وحدها لا تؤكد الليمفوما ولا تستبعدها عادة، وغالبًا تُعد خزعة النسيج ضرورية لتحديد التشخيص والنوع.','Select a stage to read about it. Not everyone has the same tests or the same order; the path depends on your situation. Blood tests alone generally cannot confirm or rule out lymphoma, and a tissue biopsy is often essential to establish the diagnosis and type.'],
treatH:['العلاج والحياة بعد التشخيص','Treatment and life after diagnosis'],
treatP:['يعتمد العلاج على نوع الليمفوما الفرعي ومدى انتشارها وصحة الشخص وتوصيات الفريق الطبي. لا يوجد علاج واحد يناسب جميع الأنواع، ولا يقدّم الموقع وصفات علاجية أو جرعات أو وعودًا بنتائج.','Treatment depends on the lymphoma subtype, how far it has spread, personal health and the care team’s recommendations. No single treatment suits every type, and this site gives no prescriptions, doses or promised outcomes.'],
liveH:['العيش مع التشخيص','Living with a diagnosis'],
mythH:['خرافات وحقائق','Myths vs. facts'],mythP:['اختر البطاقة لتكشف الحقيقة.','Select a card to reveal the fact.'],fact:['الحقيقة','Fact'],src:['المصدر','Source'],
glossH:['القاموس الطبي','Medical glossary'],search:['ابحث بالعربية أو الإنجليزية','Search in Arabic or English'],empty:['لا توجد نتائج مطابقة. جرّب كلمة أخرى.','No matching terms. Try another word.'],
faqH:['الأسئلة الشائعة','Frequently asked questions'],
askH:['أسئلة تسألها للطبيب','Questions to ask your doctor'],
askP:['اختر الأسئلة التي تهمك ثم اطبعها لتأخذها معك. هذه القائمة أداة تحضير وليست بديلًا عن المشورة الطبية.','Choose the questions that matter to you, then print them to bring along. This list is a preparation aid, not a replacement for medical advice.'],
prep:['قائمة تحضير للموعد وليست بديلًا عن المشورة الطبية.','Appointment preparation aid, not a replacement for medical advice.'],print:['اطبع الأسئلة المختارة','Print selected questions'],
refsH:['المصادر وعن المشروع','Sources and about'],
refsP:['«Beyond the Nodes» مشروع توعوي. اعتمد المحتوى العام على صفحات المعهد الوطني للسرطان (NCI) وهيئة الخدمات الصحية البريطانية (NHS). راجع هذه الصفحات للتفاصيل المحدّثة.','“Beyond the Nodes” is an awareness project. The general content draws on pages from the National Cancer Institute (NCI) and the NHS. Check these pages for current detail.'],
refNci:['المعهد الوطني للسرطان: نظرة عامة على الليمفوما (تعريف الليمفوما وأنواعها وعلاجها)','NCI: Lymphoma overview (definition, types, treatment)'],
refNhs1:['NHS: ليمفوما لاهودجكين (الأعراض والتشخيص والعلاج)','NHS: Non-Hodgkin lymphoma (symptoms, diagnosis, treatment)'],
refNhs2:['NHS: ليمفوما هودجكين (الأعراض والتشخيص والعلاج)','NHS: Hodgkin lymphoma (symptoms, diagnosis, treatment)'],
switch:['English','العربية'],langLbl:['التبديل إلى الإنجليزية','Switch to Arabic']
};
