const HS=[
{p:[[100,66]],n:['العقد الليمفاوية في الرقبة','Neck lymph nodes'],l:['على جانبي الرقبة وتحت الفك','Sides of the neck and under the jaw'],r:['ترشّح السائل الليمفاوي القادم من الرأس والرقبة وتحتضن خلايا مناعية.','Filter lymph fluid draining from the head and neck and host immune cells.'],m:['تتضخم كثيرًا مع العدوى الشائعة، والتضخم وحده لا يعني السرطان.','They often swell with ordinary infections; swelling alone does not mean cancer.']},
{p:[[66,102],[134,102]],n:['عقد الإبط','Armpit (axillary) nodes'],l:['تحت الإبطين','Under the arms'],r:['تصرّف السائل الليمفاوي من الذراع وجدار الصدر.','Drain lymph from the arm and chest wall.'],m:['قد تشمل الليمفوما عقدًا في منطقة واحدة أو عدة مناطق.','Lymphoma can involve nodes in one region or several.']},
{p:[[100,98]],n:['الغدة الصعترية / التيموسية','Thymus'],l:['خلف عظمة القص أمام القلب','Behind the breastbone, in front of the heart'],r:['تنضج فيها الخلايا الليمفاوية التائية.','Where T lymphocytes mature.'],m:['قد يشمل بعض أنواع الليمفوما الصدر، ويختلف ذلك من نوع لآخر.','Some lymphomas involve the chest; this varies by type.']},
{p:[[126,140]],n:['الطحال','Spleen'],l:['أعلى البطن من الجهة اليسرى','Upper left abdomen'],r:['ينقّي الدم ويحتوي خلايا مناعية.','Filters blood and contains immune cells.'],m:['قد يتأثر الطحال في بعض الحالات، ويقيّمه الأطباء عند الحاجة.','The spleen can be involved in some cases and is assessed when needed.']},
{p:[[100,160]],n:['عقد البطن العميقة','Deep abdominal nodes'],l:['في عمق البطن','Deep in the abdomen'],r:['تصرّف السائل الليمفاوي من أعضاء الجهاز الهضمي.','Drain lymph from digestive organs.'],m:['لا يمكن لمسها، ولذلك يُستعان بالتصوير عند الحاجة.','They cannot be felt, so imaging may be used when needed.']},
{p:[[88,202],[112,202]],n:['عقد الأربية','Groin (inguinal) nodes'],l:['حيث تلتقي الساقان بالحوض','Where the legs meet the pelvis'],r:['تصرّف السائل الليمفاوي من الساقين ومنطقة الحوض.','Drain lymph from the legs and pelvic area.'],m:['يرتبط تضخمها غالبًا بعدوى موضعية أو إصابة بسيطة، ويُقيَّم إذا استمر.','Swelling is usually linked to a local infection or minor injury; get it checked if it persists.']},
{p:[[82,126]],n:['الأوعية الليمفاوية','Lymphatic vessels'],l:['شبكة منتشرة في الجسم كله','A network throughout the body'],r:['أنابيب دقيقة تنقل السائل الليمفاوي والخلايا المناعية بين العقد.','Thin tubes carrying lymph and immune cells between nodes.'],m:['تربط المواضع الليمفاوية ببعضها، لكن الليمفوما قد تبدأ في مواضع متعددة.','They connect lymphatic sites, but lymphoma can start in many places.']},
{p:[[166,58]],n:['الخلايا الليمفاوية','Lymphocytes'],l:['تجوب الدم والعقد والأعضاء الليمفاوية','Circulate in blood, nodes and lymphatic organs'],r:['خلايا بائية وتائية وقاتلة طبيعية تدافع عن الجسم.','B, T and natural killer cells that defend the body.'],m:['تبدأ الليمفوما عندما تنمو هذه الخلايا بصورة غير طبيعية.','Lymphoma starts when these cells grow abnormally.']}];
const SY=[[['تضخم العقد أو كتل','Swollen nodes or lumps'],['انتفاخ غالبًا غير مؤلم في الرقبة أو الإبط أو الأربية.','Often painless swelling in the neck, armpit or groin.'],['إذا استمر أسابيع أو ازداد حجمه.','If it lasts weeks or keeps growing.']],
[['حمّى بلا سبب واضح','Fever without clear cause'],['ارتفاع حرارة متكرر دون عدوى ظاهرة.','Recurring fever without an obvious infection.'],['إذا تكررت أو استمرت.','If it recurs or persists.']],
[['تعرّق ليلي غزير','Drenching night sweats'],['تعرق يبلل الملابس أو الفراش.','Sweating that soaks clothes or bedding.'],['إذا تكرر دون سبب كالجو الحار.','If frequent without a reason such as a hot room.']],
[['فقدان وزن غير مبرر','Unexplained weight loss'],['نقص في الوزن دون تغيير في الغذاء أو النشاط.','Weight loss without changes in diet or activity.'],['إذا حدث دون سبب معروف.','If it happens without a known reason.']],
[['إرهاق مستمر','Persistent fatigue'],['تعب لا يتحسن بالراحة.','Tiredness that rest does not relieve.'],['إذا استمر وأثّر على حياتك اليومية.','If it persists and affects daily life.']],
[['حكة مستمرة','Persistent itching'],['حكة بلا طفح واضح.','Itching without an evident rash.'],['إذا استمرت ولم تجد لها سببًا.','If it persists with no clear cause.']]];
const TL=[[['التاريخ المرضي والفحص السريري','History and physical exam'],['يسألك الطبيب عن الأعراض والتاريخ الصحي ويفحص العقد الليمفاوية والبطن.','The doctor asks about symptoms and health history and examines your nodes and abdomen.']],
[['فحوص الدم والفحوص الأولية','Blood tests and initial investigations'],['تعطي معلومات عامة عن حالتك، لكنها لا تؤكد الليمفوما ولا تستبعدها وحدها.','They give general information about your health but cannot confirm or rule out lymphoma alone.']],
[['الخزعة وفحص النسيج','Biopsy and tissue examination'],['تؤخذ عينة من عقدة أو نسيج عند الحاجة وتُفحص مخبريًا، وغالبًا تكون ضرورية للتشخيص.','A sample of a node or tissue is taken when indicated and examined in the lab; it is often essential for diagnosis.']],
[['التصوير والفحوص الإضافية','Imaging and additional tests'],['قد تشمل الأشعة المقطعية أو غيرها، حسب الحالة.','May include CT or other scans, depending on the situation.']],
[['تحديد النوع الفرعي','Identifying the subtype'],['تساعد اختبارات خاصة على النسيج في معرفة نوع الليمفوما بدقة.','Special tests on the tissue help identify the exact lymphoma type.']],
[['تقييم مدى المرض','Assessing the extent of disease'],['يُجرى عند الحاجة لمعرفة المواضع المتأثرة.','Done when required to see which areas are affected.']],
[['مناقشة النتائج وخطة الرعاية','Discussing results and a care plan'],['يشرح الفريق الطبي النتائج ويضع معك خطة فردية.','The care team explains results and builds an individual plan with you.']]];
const TR=[[['العلاج الكيميائي','Chemotherapy'],['أدوية تستهدف الخلايا سريعة الانقسام.','Drugs that target fast-dividing cells.']],
[['العلاج الإشعاعي','Radiotherapy'],['إشعاع موجّه إلى مناطق محددة.','Radiation directed at specific areas.']],
[['العلاج المناعي','Immunotherapy'],['علاجات تساعد الجهاز المناعي على التعرّف على الخلايا السرطانية.','Treatments that help the immune system recognise cancer cells.']],
[['العلاجات الموجّهة','Targeted therapies'],['أدوية تستهدف خصائص محددة في الخلايا السرطانية.','Drugs aimed at specific features of cancer cells.']],
[['المراقبة النشطة','Active surveillance'],['متابعة دقيقة دون علاج فوري في حالات مختارة عندما يراه الطبيب مناسبًا.','Close monitoring without immediate treatment in selected cases when the doctor considers it appropriate.']],
[['الرعاية الداعمة والمتابعة','Supportive care and follow-up'],['تخفيف الأعراض والآثار الجانبية ومتابعة الصحة بعد العلاج.','Easing symptoms and side effects and monitoring health after treatment.']]];
const LV=[['الدعم النفسي: تحدّث مع من تثق بهم أو مع مختص.','Emotional support: talk with people you trust or a professional.'],['جهّز أسئلتك قبل كل موعد (انظر قائمة الأسئلة).','Prepare questions before each appointment (see the question list).'],['افهم مواعيد المتابعة والفحوص المطلوبة.','Understand follow-up appointments and the tests needed.'],['أبلغ الفريق الطبي بمخاوفك وآثارك الجانبية.','Tell your care team about concerns and side effects.'],['ابحث عن الدعم من جهات موثوقة مثل المصادر المدرجة أدناه.','Look for support from trustworthy sources such as those listed below.']];
